sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }
    g_form.getReference('name', function(user) {
        if (!user) return;

        g_form.setValue('number', user.u_number || '');
        g_form.setValue('name_kanji', user.u_ukanji_name || '');

        if (g_form.getValue('type') === 'gen') {
            var shozokuId = user.u_shozoku;
            if (shozokuId) {
                var ga = new GlideAjax('ShozokuInfoAPI'); // ← Script Include 名
                ga.addParam('sysparm_name', 'getYakuiAndBumon');
                ga.addParam('sysparm_shozoku', shozokuId);
                ga.getXMLAnswer(function(resp) {
                    if (!resp) return;
                    try {
                        var data = JSON.parse(resp);
                        g_form.setValue('yakui_kyuu', data.yakui || '');
                        g_form.setValue('shumu_kyuu', data.bumon || '');
						g_form.setValue('kimuti_kyuu', data.kinmuti || '');
                        g_form.setValue('tyokkan_kyuu', data.tyokkan || '');
                    } catch (e) {
                        console.log('エラー');
                    }
                });
            } else {
                g_form.setValue('yakui_kyuu', '');
                g_form.setValue('shumu_kyuu', '');
            }
        }

}
